// Bitmap fonts for labels, generated by tools/genfont.
#pragma once

#include <stdint.h>

// A glyph's 1-bit bitmap is rows of (w + 7) / 8 bytes, bit 7 = leftmost. (x, y)
// is the bitmap's top-left corner relative to the pen position on the baseline,
// so y is negative above it.
typedef struct {
    uint32_t off;
    uint8_t w, h;
    int8_t x, y;
    uint8_t adv;
} glyph_t;

// Glyphs cover the printable ASCII characters 32 to 126, indexed from 32.
typedef struct {
    uint8_t ascent, descent;
    const glyph_t *glyphs;
    const uint8_t *bits;
} font_t;

extern const font_t font_large, font_medium, font_small, font_caption;
